package com.snipify.handler;
import com.amazonaws.services.lambda.runtime.*;import com.amazonaws.services.lambda.runtime.events.*;import com.snipify.cache.RedisCache;import com.snipify.model.UrlMapping;import com.snipify.repository.UrlRepository;import software.amazon.awssdk.services.dynamodb.DynamoDbClient;import java.time.Instant;import java.util.Map;import java.util.Optional;
public class RedirectUrlHandler implements RequestHandler<APIGatewayV2HTTPEvent,APIGatewayV2HTTPResponse>{
 private static final UrlRepository REPO=new UrlRepository(DynamoDbClient.create(),env("TABLE_NAME"));private static final RedisCache CACHE=new RedisCache(env("REDIS_HOST"),Integer.parseInt(env("REDIS_PORT")),Integer.parseInt(env("CACHE_TTL_SECONDS")));
 public APIGatewayV2HTTPResponse handleRequest(APIGatewayV2HTTPEvent e,Context c){String code=e.getPathParameters()==null?null:e.getPathParameters().get("shortCode");if(code==null||!code.matches("[0-9A-Za-z]{7}"))return ApiResponses.json(400,"{\"message\":\"Invalid short code\"}");try{Optional<UrlMapping> m=Optional.empty();String source="REDIS";try{m=CACHE.get(code);}catch(Exception ce){c.getLogger().log("Cache read skipped: "+ce.getMessage());}if(m.isEmpty()){source="DYNAMODB";m=REPO.find(code);m.filter(this::valid).ifPresent(v->{try{CACHE.put(v);}catch(Exception ignored){}});}if(m.isEmpty()||!valid(m.get()))return ApiResponses.json(404,"{\"message\":\"Short URL not found or expired\"}");return APIGatewayV2HTTPResponse.builder().withStatusCode(302).withHeaders(Map.of("location",m.get().originalUrl(),"cache-control","no-store","x-cache-source",source)).withBody("").build();}catch(Exception x){c.getLogger().log("Resolve failed: "+x);return ApiResponses.json(500,"{\"message\":\"Internal server error\"}");}}
 private boolean valid(UrlMapping m){return "ACTIVE".equals(m.status())&&m.expiresAt()>Instant.now().getEpochSecond();}private static String env(String n){String v=System.getenv(n);if(v==null||v.isBlank())throw new IllegalStateException(n+" required");return v;}
}
